VALUES
    (282001, 281001, FALSE, '{"text":"토끼 선수는 단단한 경주 바퀴를 차분하게 점검했어요. 두 선수는 첫 번째 굽은 길을 안전하게 지나갔어요. 두 선수는 단단한 경주 바퀴를 차분하게 점검했어요.","sentences":["토끼 선수는 단단한 경주 바퀴를 차분하게 점검했어요.","두 선수는 첫 번째 굽은 길을 안전하게 지나갔어요.","두 선수는 단단한 경주 바퀴를 차분하게 점검했어요."],"pageNo":1}', NULL, 1, '2026-08-04 15:01:00', '2026-08-04 15:01:00', 0),
    (282002, 281001, FALSE, '{"text":"숲속 친구들은 첫 번째 굽은 길을 안전하게 지나갔어요. 안전 요원은 첫 번째 굽은 길을 안전하게 지나갔어요. 안전 요원은 단단한 경주 바퀴를 차분하게 점검했어요.","sentences":["숲속 친구들은 첫 번째 굽은 길을 안전하게 지나갔어요.","안전 요원은 첫 번째 굽은 길을 안전하게 지나갔어요.","안전 요원은 단단한 경주 바퀴를 차분하게 점검했어요."],"pageNo":2}', NULL, 2, '2026-08-04 15:02:00', '2026-08-04 15:02:00', 0),
    (282003, 281001, FALSE, '{"text":"거북이 선수는 첫 번째 굽은 길을 안전하게 지나갔어요. 토끼 선수는 첫 번째 굽은 길을 안전하게 지나갔어요. 두 선수는 서로 첫 번째 굽은 길을 안전하게 지나갔어요.","sentences":["거북이 선수는 첫 번째 굽은 길을 안전하게 지나갔어요.","토끼 선수는 첫 번째 굽은 길을 안전하게 지나갔어요.","두 선수는 서로 첫 번째 굽은 길을 안전하게 지나갔어요."],"pageNo":3}', NULL, 3, '2026-08-04 15:03:00', '2026-08-04 15:03:00', 0),
    (282004, 281001, TRUE, '{"text":"두 선수는 다음 코너에서 어떤 작전을 고를까요?","sentences":["두 선수는 다음 코너에서 어떤 작전을 고를까요?"],"pageNo":4}', '{"subtitle":"두 선수는 다음 코너에서 어떤 작전을 고를까요?","options":[{"optionNo":1,"label":"안쪽 길을 천천히 달려요"},{"optionNo":2,"label":"바깥 길에서 속도를 높여요"},{"optionNo":3,"label":"안전 요원에게 길을 물어요"}]}', 4, '2026-08-04 15:04:00', '2026-08-04 15:04:00', 0),
    (282005, 281002, FALSE, '{"text":"거북이 선수는 용기 내어 주의 깊게 바라보았어요. 토끼 선수는 서로 차분하게 점검했어요. 토끼 선수는 오늘도 차분하게 점검했어요.","sentences":["거북이 선수는 용기 내어 주의 깊게 바라보았어요.","토끼 선수는 서로 차분하게 점검했어요.","토끼 선수는 오늘도 차분하게 점검했어요."],"pageNo":5}', NULL, 1, '2026-08-04 15:05:00', '2026-08-04 15:05:00', 0),
    (282006, 281002, FALSE, '{"text":"토끼 선수는 용기 내어 차분하게 점검했어요. 두 선수는 오늘도 안전하게 지나갔어요. 두 선수는 용기 내어 안전하게 지나갔어요.","sentences":["토끼 선수는 용기 내어 차분하게 점검했어요.","두 선수는 오늘도 안전하게 지나갔어요.","두 선수는 용기 내어 안전하게 지나갔어요."],"pageNo":6}', NULL, 2, '2026-08-04 15:06:00', '2026-08-04 15:06:00', 0),
    (282007, 281002, FALSE, '{"text":"두 선수는 차분히 안전하게 지나갔어요. 두 선수는 서로 안전하게 지나갔어요. 토끼 선수는 서로 주의 깊게 바라보았어요.","sentences":["두 선수는 차분히 안전하게 지나갔어요.","두 선수는 서로 안전하게 지나갔어요.","토끼 선수는 서로 주의 깊게 바라보았어요."],"pageNo":7}', NULL, 3, '2026-08-04 15:07:00', '2026-08-04 15:07:00', 0),
    (282008, 281002, FALSE, '{"text":"토끼 선수는 오늘도 주의 깊게 바라보았어요. 토끼 선수는 용기 내어 주의 깊게 바라보았어요. 토끼 선수는 차분히 주의 깊게 바라보았어요.","sentences":["토끼 선수는 오늘도 주의 깊게 바라보았어요.","토끼 선수는 용기 내어 주의 깊게 바라보았어요.","토끼 선수는 차분히 주의 깊게 바라보았어요."],"pageNo":8}', NULL, 4, '2026-08-04 15:08:00', '2026-08-04 15:08:00', 0),
    (282009, 281002, TRUE, '{"text":"마지막 직선에서는 어떤 방법으로 달릴까요?","sentences":["마지막 직선에서는 어떤 방법으로 달릴까요?"],"pageNo":9}', '{"subtitle":"마지막 직선에서는 어떤 방법으로 달릴까요?","options":[{"optionNo":1,"label":"남은 힘으로 끝까지 달려요"},{"optionNo":2,"label":"서로 응원하며 나란히 달려요"},{"optionNo":3,"label":"잠시 바퀴를 다시 살펴봐요"}]}', 5, '2026-08-04 15:09:00', '2026-08-04 15:09:00', 0),
    (282010, 281003, FALSE, '{"text":"별주부는 반짝이는 바닷길을 천천히 안내했어요. 토끼는 용왕의 아픈 사연을 차분하게 들려주었어요. 토끼는 반짝이는 바닷길을 천천히 안내했어요.","sentences":["별주부는 반짝이는 바닷길을 천천히 안내했어요.","토끼는 용왕의 아픈 사연을 차분하게 들려주었어요.","토끼는 반짝이는 바닷길을 천천히 안내했어요."],"pageNo":1}', NULL, 1, '2026-08-03 15:01:00', '2026-08-03 15:01:00', 0),
    (282011, 281003, FALSE, '{"text":"용궁 친구들은 반짝이는 바닷길을 천천히 안내했어요. 바다 거북은 반짝이는 바닷길을 천천히 안내했어요. 별주부는 서로의 걱정과 생각을 솔직하게 나누었어요.","sentences":["용궁 친구들은 반짝이는 바닷길을 천천히 안내했어요.","바다 거북은 반짝이는 바닷길을 천천히 안내했어요.","별주부는 서로의 걱정과 생각을 솔직하게 나누었어요."],"pageNo":2}', NULL, 2, '2026-08-03 15:02:00', '2026-08-03 15:02:00', 0),
    (282012, 281003, FALSE, '{"text":"별주부는 용왕의 아픈 사연을 차분하게 들려주었어요. 토끼는 서로의 걱정과 생각을 솔직하게 나누었어요. 토끼는 서로 반짝이는 바닷길을 천천히 안내했어요.","sentences":["별주부는 용왕의 아픈 사연을 차분하게 들려주었어요.","토끼는 서로의 걱정과 생각을 솔직하게 나누었어요.","토끼는 서로 반짝이는 바닷길을 천천히 안내했어요."],"pageNo":3}', NULL, 3, '2026-08-03 15:03:00', '2026-08-03 15:03:00', 0),
    (282013, 281003, TRUE, '{"text":"토끼는 용궁에서 어떤 지혜를 먼저 낼까요?","sentences":["토끼는 용궁에서 어떤 지혜를 먼저 낼까요?"],"pageNo":4}', '{"subtitle":"토끼는 용궁에서 어떤 지혜를 먼저 낼까요?","options":[{"optionNo":1,"label":"용왕에게 다른 약을 찾아보자고 해요"},{"optionNo":2,"label":"별주부와 육지로 함께 돌아가요"},{"optionNo":3,"label":"용궁 친구들의 생각을 먼저 들어요"}]}', 4, '2026-08-03 15:04:00', '2026-08-03 15:04:00', 0),
    (282014, 281004, FALSE, '{"text":"둘째 돼지는 필요한 도구와 재료를 하나씩 정리했어요. 막내 돼지는 서로 잘하는 집안일을 즐겁게 나누었어요. 막내 돼지는 필요한 도구와 재료를 하나씩 정리했어요.","sentences":["둘째 돼지는 필요한 도구와 재료를 하나씩 정리했어요.","막내 돼지는 서로 잘하는 집안일을 즐겁게 나누었어요.","막내 돼지는 필요한 도구와 재료를 하나씩 정리했어요."],"pageNo":1}', NULL, 1, '2026-07-08 15:01:00', '2026-07-08 15:01:00', 0),
    (282015, 281004, FALSE, '{"text":"세 형제는 서로 잘하는 집안일을 즐겁게 나누었어요. 세 형제는 필요한 도구와 재료를 하나씩 정리했어요. 세 형제는 새집을 지을 빈터를 꼼꼼하게 살펴보았어요.","sentences":["세 형제는 서로 잘하는 집안일을 즐겁게 나누었어요.","세 형제는 필요한 도구와 재료를 하나씩 정리했어요.","세 형제는 새집을 지을 빈터를 꼼꼼하게 살펴보았어요."],"pageNo":2}', NULL, 2, '2026-07-08 15:02:00', '2026-07-08 15:02:00', 0),
    (282016, 281004, FALSE, '{"text":"첫째 돼지는 서로 잘하는 집안일을 즐겁게 나누었어요. 첫째 돼지는 필요한 도구와 재료를 하나씩 정리했어요. 둘째 돼지는 서로 잘하는 집안일을 즐겁게 나누었어요.","sentences":["첫째 돼지는 서로 잘하는 집안일을 즐겁게 나누었어요.","첫째 돼지는 필요한 도구와 재료를 하나씩 정리했어요.","둘째 돼지는 서로 잘하는 집안일을 즐겁게 나누었어요."],"pageNo":3}', NULL, 3, '2026-07-08 15:03:00', '2026-07-08 15:03:00', 0),
    (282017, 281004, TRUE, '{"text":"세 형제는 이제 어떤 재료를 먼저 고를까요?","sentences":["세 형제는 이제 어떤 재료를 먼저 고를까요?"],"pageNo":4}', '{"subtitle":"세 형제는 이제 어떤 재료를 먼저 고를까요?","options":[{"optionNo":1,"label":"벽돌을 차곡차곡 더 쌓아요"},{"optionNo":2,"label":"나무 기둥을 먼저 점검해요"},{"optionNo":3,"label":"이웃들과 안전 계획을 세워요"}]}', 4, '2026-07-08 15:04:00', '2026-07-08 15:04:00', 0),
    (282018, 281005, FALSE, '{"text":"첫째 돼지는 용기 내어 꼼꼼하게 살펴보았어요. 둘째 돼지는 서로 하나씩 정리했어요. 둘째 돼지는 오늘도 하나씩 정리했어요.","sentences":["첫째 돼지는 용기 내어 꼼꼼하게 살펴보았어요.","둘째 돼지는 서로 하나씩 정리했어요.","둘째 돼지는 오늘도 하나씩 정리했어요."],"pageNo":5}', NULL, 1, '2026-07-08 15:05:00', '2026-07-08 15:05:00', 0),
    (282019, 281005, FALSE, '{"text":"둘째 돼지는 용기 내어 하나씩 정리했어요. 둘째 돼지는 차분히 하나씩 정리했어요. 막내 돼지는 오늘도 즐겁게 나누었어요.","sentences":["둘째 돼지는 용기 내어 하나씩 정리했어요.","둘째 돼지는 차분히 하나씩 정리했어요.","막내 돼지는 오늘도 즐겁게 나누었어요."],"pageNo":6}', NULL, 2, '2026-07-08 15:06:00', '2026-07-08 15:06:00', 0),
