    (282127, 281037, TRUE, '{"text":"어부는 넓은 바다에서 어느 길을 고를까요?","sentences":["어부는 넓은 바다에서 어느 길을 고를까요?"],"pageNo":14}', '{"subtitle":"어부는 넓은 바다에서 어느 길을 고를까요?","options":[{"optionNo":1,"label":"햇빛이 비치는 물결을 따라가요"},{"optionNo":2,"label":"바다새가 나는 쪽을 살펴봐요"},{"optionNo":3,"label":"잠시 배를 멈추고 지도를 봐요"}]}', 4, '2026-08-04 16:14:00', '2026-08-04 16:14:00', 0),
